-- ============================================================================
-- Migration: POS > Generate GC Compliment Module (Outlet 111)
-- Date: 2026-11-27
-- Author: Zen Family Spa Architect
-- Description:
--   1. Creates public.ot_pos_gc_compliment table to store complimentary Gift
--      Certificates generated by Roles 5, 6 (strictly kode_outlet = '111'),
--      and 8 before and after activation to public.ot_pos_gc_transaction.
--   2. Creates public storage bucket 'gc-compliment-images' with strict
--      authenticated write policies for Roles 5, 6 (kode_outlet='111'), and 8.
--   3. Creates centralized SECURITY DEFINER RPCs:
--      - public.generate_pos_gc_compliments(...)
--      - public.update_pos_gc_compliment_images(...)
--      - public.activate_pos_gc_compliments(...)
--      - public.get_pos_gc_compliment_list(...)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Table: public.ot_pos_gc_compliment
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ot_pos_gc_compliment (
  uid UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  gc_number TEXT NOT NULL UNIQUE,
  gc_barcode TEXT NOT NULL,
  qrcode TEXT NOT NULL UNIQUE,
  pack_number TEXT,
  web_service_id UUID REFERENCES public.web_services(id) ON DELETE SET NULL,
  service_name TEXT,
  service_category TEXT,
  duration_minutes INTEGER,
  background_image_url TEXT,
  nama_gc TEXT NOT NULL,
  harga_jasa NUMERIC(15, 2) NOT NULL DEFAULT 0,
  harga_jual NUMERIC(15, 2) NOT NULL DEFAULT 0,
  kode_outlet TEXT NOT NULL DEFAULT '111',
  image_url TEXT,
  is_active BOOLEAN NOT NULL DEFAULT false,
  is_sold BOOLEAN NOT NULL DEFAULT false,
  has_used BOOLEAN NOT NULL DEFAULT false,
  expired_date DATE,
  id_payment_buy TEXT,
  activated_at TIMESTAMPTZ,
  activated_by UUID,
  activated_by_name TEXT,
  notes TEXT,
  email_sent_to TEXT,
  email_sent_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID,
  created_by_name TEXT
);

CREATE INDEX IF NOT EXISTS idx_ot_pos_gc_compliment_created_at
  ON public.ot_pos_gc_compliment (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_ot_pos_gc_compliment_is_active
  ON public.ot_pos_gc_compliment (is_active);

CREATE INDEX IF NOT EXISTS idx_ot_pos_gc_compliment_gc_barcode
  ON public.ot_pos_gc_compliment (gc_barcode);

CREATE INDEX IF NOT EXISTS idx_ot_pos_gc_compliment_pack_number
  ON public.ot_pos_gc_compliment (pack_number);

CREATE INDEX IF NOT EXISTS idx_ot_pos_gc_compliment_web_service_id
  ON public.ot_pos_gc_compliment (web_service_id);

ALTER TABLE public.ot_pos_gc_compliment ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow authorized roles read ot_pos_gc_compliment" ON public.ot_pos_gc_compliment;
CREATE POLICY "Allow authorized roles read ot_pos_gc_compliment"
  ON public.ot_pos_gc_compliment
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1
      FROM public.users_profile up
      WHERE up.uid = auth.uid()
        AND (
          up.user_role IN (5, 8)
          OR (up.user_role = 6 AND NULLIF(TRIM(up.kode_outlet), '') = '111')
        )
    )
  );

REVOKE ALL ON TABLE public.ot_pos_gc_compliment FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.ot_pos_gc_compliment TO authenticated;
GRANT ALL ON TABLE public.ot_pos_gc_compliment TO service_role;

-- ----------------------------------------------------------------------------
-- 2. Storage Bucket: gc-compliment-images
-- ----------------------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'gc-compliment-images',
  'gc-compliment-images',
  true,
  10485760,
  ARRAY['image/png', 'image/jpeg', 'image/webp']
)
ON CONFLICT (id) DO UPDATE SET
  public = true,
  file_size_limit = 10485760,
  allowed_mime_types = ARRAY['image/png', 'image/jpeg', 'image/webp'];

DROP POLICY IF EXISTS "Public Access for GC Compliment Images" ON storage.objects;
CREATE POLICY "Public Access for GC Compliment Images"
  ON storage.objects FOR SELECT
  TO public
  USING (bucket_id = 'gc-compliment-images');

DROP POLICY IF EXISTS "Authorized roles can upload gc compliment images" ON storage.objects;
CREATE POLICY "Authorized roles can upload gc compliment images"
  ON storage.objects FOR INSERT
  TO authenticated
  WITH CHECK (
    bucket_id = 'gc-compliment-images'
    AND EXISTS (
      SELECT 1
      FROM public.users_profile up
      WHERE up.uid = auth.uid()
        AND (
          up.user_role IN (5, 8)
          OR (up.user_role = 6 AND NULLIF(TRIM(up.kode_outlet), '') = '111')
        )
    )
  );

DROP POLICY IF EXISTS "Authorized roles can update gc compliment images" ON storage.objects;
CREATE POLICY "Authorized roles can update gc compliment images"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'gc-compliment-images'
    AND EXISTS (
      SELECT 1
      FROM public.users_profile up
      WHERE up.uid = auth.uid()
        AND (
          up.user_role IN (5, 8)
          OR (up.user_role = 6 AND NULLIF(TRIM(up.kode_outlet), '') = '111')
        )
    )
  );

DROP POLICY IF EXISTS "Authorized roles can delete gc compliment images" ON storage.objects;
CREATE POLICY "Authorized roles can delete gc compliment images"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'gc-compliment-images'
    AND EXISTS (
      SELECT 1
      FROM public.users_profile up
      WHERE up.uid = auth.uid()
        AND (
          up.user_role IN (5, 8)
          OR (up.user_role = 6 AND NULLIF(TRIM(up.kode_outlet), '') = '111')
        )
    )
  );

-- ----------------------------------------------------------------------------
-- 3. Internal Helper Functions
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._assert_gc_compliment_access()
RETURNS TABLE (
  user_uid UUID,
  user_role INTEGER,
  user_outlet TEXT,
  user_name TEXT
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_role INTEGER;
  v_outlet TEXT;
  v_name TEXT;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Autentikasi diperlukan.' USING ERRCODE = '42501';
  END IF;

  SELECT
    up.user_role,
    NULLIF(TRIM(up.kode_outlet), ''),
    COALESCE(NULLIF(TRIM(up.full_name), ''), NULLIF(TRIM(up.email), ''), v_uid::text)
  INTO v_role, v_outlet, v_name
  FROM public.users_profile up
  WHERE up.uid = v_uid;

  IF v_role IS NULL OR NOT (v_role IN (5, 8) OR (v_role = 6 AND v_outlet = '111')) THEN
    RAISE EXCEPTION 'Akses ditolak. Hanya Role 5, Role 8, atau Role 6 Outlet 111 yang berwenang mengakses Generate GC Compliment.'
      USING ERRCODE = '42501';
  END IF;

  user_uid := v_uid;
  user_role := v_role;
  user_outlet := v_outlet;
  user_name := v_name;
  RETURN NEXT;
END;
$$;

REVOKE ALL ON FUNCTION public._assert_gc_compliment_access() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public._generate_gc_qrcode(p_length INTEGER DEFAULT 24)
RETURNS TEXT
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_alphabet CONSTANT TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_len INTEGER := LEAST(GREATEST(COALESCE(p_length, 24), 15), 32);
  v_hex TEXT;
  v_bytes BYTEA;
  v_result TEXT := '';
  v_idx INTEGER;
BEGIN
  v_hex := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  v_bytes := decode(v_hex, 'hex');

  FOR v_idx IN 0 .. (v_len - 1) LOOP
    v_result := v_result || substr(v_alphabet, (get_byte(v_bytes, v_idx) % 32) + 1, 1);
  END LOOP;

  RETURN v_result;
END;
$$;

REVOKE ALL ON FUNCTION public._generate_gc_qrcode(INTEGER) FROM PUBLIC, anon, authenticated;

-- ----------------------------------------------------------------------------
-- 4. RPC: public.generate_pos_gc_compliments(...)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.generate_pos_gc_compliments(
  p_prefix TEXT,
  p_start_number INTEGER,
  p_count INTEGER,
  p_web_service_id UUID,
  p_nama_gc TEXT,
  p_harga_jasa NUMERIC,
  p_harga_jual NUMERIC,
  p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_uid UUID;
  v_actor_role INTEGER;
  v_actor_outlet TEXT;
  v_actor_name TEXT;

  v_clean_prefix TEXT;
  v_nama_gc TEXT := TRIM(COALESCE(p_nama_gc, ''));
  v_notes TEXT := NULLIF(TRIM(COALESCE(p_notes, '')), '');

  v_svc_name TEXT;
  v_svc_category TEXT;
  v_svc_duration INTEGER;
  v_svc_bg_url TEXT;

  v_idx INTEGER;
  v_seq INTEGER;
  v_gc_number TEXT;
  v_gc_barcode TEXT;
  v_qrcode TEXT;
  v_qr_attempt INTEGER;

  v_inserted_row public.ot_pos_gc_compliment%ROWTYPE;
  v_rows JSONB := '[]'::jsonb;
BEGIN
  SELECT user_uid, user_role, user_outlet, user_name
  INTO v_actor_uid, v_actor_role, v_actor_outlet, v_actor_name
  FROM public._assert_gc_compliment_access();

  -- Sanitize & validate prefix after '111.'
  v_clean_prefix := UPPER(TRIM(BOTH '.' FROM TRIM(COALESCE(p_prefix, ''))));
  IF v_clean_prefix = '' THEN
    RAISE EXCEPTION 'Prefix GC setelah "111." wajib diisi.' USING ERRCODE = '22023';
  END IF;
  IF v_clean_prefix !~ '^[A-Z0-9._-]+$' THEN
    RAISE EXCEPTION 'Prefix GC hanya boleh menggunakan huruf, angka, titik (.), garis bawah (_), atau tanda hubung (-).'
      USING ERRCODE = '22023';
  END IF;

  IF p_start_number IS NULL OR p_start_number < 1 THEN
    RAISE EXCEPTION 'Nomor urut awal minimal 1.' USING ERRCODE = '22023';
  END IF;

  IF p_count IS NULL OR p_count < 1 OR p_count > 100 THEN
    RAISE EXCEPTION 'Jumlah GC yang dibuat harus antara 1 sampai 100 per batch.' USING ERRCODE = '22023';
  END IF;

  IF v_nama_gc = '' THEN
    RAISE EXCEPTION 'Nama GC wajib diisi.' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_harga_jasa, -1) < 0 OR COALESCE(p_harga_jual, -1) < 0 THEN
    RAISE EXCEPTION 'Harga jasa dan harga jual tidak boleh bernilai negatif.' USING ERRCODE = '22023';
  END IF;

  IF p_web_service_id IS NOT NULL THEN
    SELECT name, category, duration_minutes, image_url
    INTO v_svc_name, v_svc_category, v_svc_duration, v_svc_bg_url
    FROM public.web_services
    WHERE id = p_web_service_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Layanan (web_services) tidak ditemukan.' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  FOR v_idx IN 0 .. (p_count - 1) LOOP
    v_seq := p_start_number + v_idx;
    v_gc_number := '111.' || v_clean_prefix || '.' || LPAD(v_seq::text, GREATEST(4, length(v_seq::text)), '0');

    -- Check collision across BOTH compliment draft/issued table AND live POS GC transactions
    IF EXISTS (SELECT 1 FROM public.ot_pos_gc_compliment WHERE gc_number = v_gc_number)
       OR EXISTS (SELECT 1 FROM public.ot_pos_gc_transaction WHERE gc_number = v_gc_number) THEN
      RAISE EXCEPTION 'Nomor GC % sudah ada di sistem. Gunakan prefix atau nomor urut awal yang berbeda.', v_gc_number
        USING ERRCODE = '23505';
    END IF;

    v_gc_barcode := regexp_replace(v_gc_number, '[^0-9]', '', 'g');

    -- Generate high-entropy unique 24-char QR code across both tables
    v_qrcode := NULL;
    FOR v_qr_attempt IN 1 .. 10 LOOP
      v_qrcode := public._generate_gc_qrcode(24);
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.ot_pos_gc_compliment WHERE qrcode = v_qrcode)
            AND NOT EXISTS (SELECT 1 FROM public.ot_pos_gc_transaction WHERE qrcode = v_qrcode);
      v_qrcode := NULL;
    END LOOP;

    IF v_qrcode IS NULL THEN
      RAISE EXCEPTION 'Gagal menghasilkan QR Code unik setelah 10 percobaan.' USING ERRCODE = '23505';
    END IF;

    INSERT INTO public.ot_pos_gc_compliment (
      gc_number,
      gc_barcode,
      qrcode,
      pack_number,
      web_service_id,
      service_name,
      service_category,
      duration_minutes,
      background_image_url,
      nama_gc,
      harga_jasa,
      harga_jual,
      kode_outlet,
      is_active,
      is_sold,
      has_used,
      notes,
      created_at,
      created_by,
      created_by_name
    )
    VALUES (
      v_gc_number,
      v_gc_barcode,
      v_qrcode,
      NULL,
      p_web_service_id,
      v_svc_name,
      v_svc_category,
      v_svc_duration,
      v_svc_bg_url,
      v_nama_gc,
      ROUND(COALESCE(p_harga_jasa, 0)::numeric, 2),
      ROUND(COALESCE(p_harga_jual, 0)::numeric, 2),
      '111',
      false,
      false,
      false,
      v_notes,
      now(),
      v_actor_uid,
      v_actor_name
    )
    RETURNING * INTO v_inserted_row;

    v_rows := v_rows || jsonb_build_array(
      jsonb_build_object(
        'uid', v_inserted_row.uid,
        'gc_number', v_inserted_row.gc_number,
        'gc_barcode', v_inserted_row.gc_barcode,
        'qrcode', v_inserted_row.qrcode,
        'pack_number', v_inserted_row.pack_number,
        'web_service_id', v_inserted_row.web_service_id,
        'service_name', v_inserted_row.service_name,
        'service_category', v_inserted_row.service_category,
        'duration_minutes', v_inserted_row.duration_minutes,
        'background_image_url', v_inserted_row.background_image_url,
        'nama_gc', v_inserted_row.nama_gc,
        'harga_jasa', v_inserted_row.harga_jasa,
        'harga_jual', v_inserted_row.harga_jual,
        'kode_outlet', v_inserted_row.kode_outlet,
        'image_url', v_inserted_row.image_url,
        'is_active', v_inserted_row.is_active,
        'is_sold', v_inserted_row.is_sold,
        'has_used', v_inserted_row.has_used,
        'expired_date', v_inserted_row.expired_date,
        'id_payment_buy', v_inserted_row.id_payment_buy,
        'activated_at', v_inserted_row.activated_at,
        'activated_by', v_inserted_row.activated_by,
        'activated_by_name', v_inserted_row.activated_by_name,
        'notes', v_inserted_row.notes,
        'email_sent_to', v_inserted_row.email_sent_to,
        'email_sent_at', v_inserted_row.email_sent_at,
        'created_at', v_inserted_row.created_at,
        'created_by', v_inserted_row.created_by,
        'created_by_name', v_inserted_row.created_by_name
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'count', p_count,
    'rows', v_rows
  );
END;
$$;

REVOKE ALL ON FUNCTION public.generate_pos_gc_compliments(TEXT, INTEGER, INTEGER, UUID, TEXT, NUMERIC, NUMERIC, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.generate_pos_gc_compliments(TEXT, INTEGER, INTEGER, UUID, TEXT, NUMERIC, NUMERIC, TEXT) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 5. RPC: public.update_pos_gc_compliment_images(...)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_pos_gc_compliment_images(
  p_items JSONB
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_uid UUID;
  v_actor_role INTEGER;
  v_actor_outlet TEXT;
  v_actor_name TEXT;
  v_item JSONB;
  v_uid UUID;
  v_image_url TEXT;
  v_updated INTEGER := 0;
BEGIN
  SELECT user_uid, user_role, user_outlet, user_name
  INTO v_actor_uid, v_actor_role, v_actor_outlet, v_actor_name
  FROM public._assert_gc_compliment_access();

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'Parameter p_items harus berupa array JSON.' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_uid := NULLIF(TRIM(COALESCE(v_item->>'uid', '')), '')::uuid;
    v_image_url := NULLIF(TRIM(COALESCE(v_item->>'image_url', '')), '');

    IF v_uid IS NOT NULL AND v_image_url IS NOT NULL THEN
      UPDATE public.ot_pos_gc_compliment
      SET image_url = v_image_url
      WHERE uid = v_uid;

      IF FOUND THEN
        v_updated := v_updated + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN v_updated;
END;
$$;

REVOKE ALL ON FUNCTION public.update_pos_gc_compliment_images(JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_pos_gc_compliment_images(JSONB) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 6. RPC: public.activate_pos_gc_compliments(...)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.activate_pos_gc_compliments(
  p_gc_uids UUID[],
  p_pack_number TEXT,
  p_buy_at TIMESTAMPTZ DEFAULT NULL,
  p_local_date DATE DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_uid UUID;
  v_actor_role INTEGER;
  v_actor_outlet TEXT;
  v_actor_name TEXT;

  v_unique_uids UUID[];
  v_pack TEXT := TRIM(COALESCE(p_pack_number, ''));
  v_buy_at TIMESTAMPTZ := COALESCE(p_buy_at, now());
  v_local_date DATE := COALESCE(p_local_date, (COALESCE(p_buy_at, now()) AT TIME ZONE 'Asia/Jakarta')::date);
  v_expired_date DATE;
  v_id_payment TEXT;

  v_locked_count INTEGER := 0;
  v_rec RECORD;
  v_rows JSONB := '[]'::jsonb;
BEGIN
  SELECT user_uid, user_role, user_outlet, user_name
  INTO v_actor_uid, v_actor_role, v_actor_outlet, v_actor_name
  FROM public._assert_gc_compliment_access();

  SELECT array_agg(DISTINCT u)
  INTO v_unique_uids
  FROM unnest(COALESCE(p_gc_uids, ARRAY[]::UUID[])) u
  WHERE u IS NOT NULL;

  IF v_unique_uids IS NULL OR COALESCE(array_length(v_unique_uids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'Pilih minimal 1 GC Compliment yang akan diaktifkan.' USING ERRCODE = '22023';
  END IF;

  IF v_pack = '' THEN
    RAISE EXCEPTION 'Pack Number wajib diisi saat mengaktifkan GC.' USING ERRCODE = '22023';
  END IF;

  v_expired_date := v_local_date + 120;
  v_id_payment := 'WHMAPP.111.'
    || to_char(v_buy_at AT TIME ZONE 'Asia/Jakarta', 'YYYYMMDDHH24MISS')
    || '.'
    || UPPER(substr(replace(gen_random_uuid()::text, '-', ''), 1, 4));

  -- Lock all target rows atomically in deterministic order
  FOR v_rec IN
    SELECT *
    FROM public.ot_pos_gc_compliment
    WHERE uid = ANY(v_unique_uids)
    ORDER BY gc_number ASC
    FOR UPDATE
  LOOP
    v_locked_count := v_locked_count + 1;

    IF v_rec.is_active = true THEN
      RAISE EXCEPTION 'GC % sudah aktif sebelumnya dan tidak dapat diaktifkan ulang.', v_rec.gc_number
        USING ERRCODE = '22023';
    END IF;

    IF EXISTS (SELECT 1 FROM public.ot_pos_gc_transaction WHERE gc_number = v_rec.gc_number) THEN
      RAISE EXCEPTION 'Nomor GC % sudah terdaftar pada transaksi POS (ot_pos_gc_transaction).', v_rec.gc_number
        USING ERRCODE = '23505';
    END IF;

    IF EXISTS (SELECT 1 FROM public.ot_pos_gc_transaction WHERE qrcode = v_rec.qrcode) THEN
      RAISE EXCEPTION 'QR Code untuk GC % sudah terdaftar pada transaksi POS (ot_pos_gc_transaction).', v_rec.gc_number
        USING ERRCODE = '23505';
    END IF;
  END LOOP;

  IF v_locked_count <> array_length(v_unique_uids, 1) THEN
    RAISE EXCEPTION 'Sebagian data GC Compliment tidak ditemukan.' USING ERRCODE = 'P0002';
  END IF;

  -- Insert all selected GCs into public.ot_pos_gc_transaction
  INSERT INTO public.ot_pos_gc_transaction (
    gc_number,
    gc_barcode,
    qrcode,
    pack_number,
    nama_gc,
    value,
    buy_at,
    expired_date,
    has_used,
    is_active,
    id_payment_buy,
    kode_outlet_buy,
    created_at,
    created_by
  )
  SELECT
    c.gc_number,
    c.gc_barcode,
    c.qrcode,
    v_pack,
    c.nama_gc,
    COALESCE(c.harga_jasa, 0)::double precision,
    v_buy_at,
    v_expired_date,
    false,
    true,
    v_id_payment,
    '111',
    now(),
    v_actor_uid
  FROM public.ot_pos_gc_compliment c
  WHERE c.uid = ANY(v_unique_uids);

  -- Update compliment registry status & metadata
  UPDATE public.ot_pos_gc_compliment
  SET
    is_active = true,
    is_sold = true,
    pack_number = v_pack,
    id_payment_buy = v_id_payment,
    expired_date = v_expired_date,
    activated_at = v_buy_at,
    activated_by = v_actor_uid,
    activated_by_name = v_actor_name
  WHERE uid = ANY(v_unique_uids);

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'uid', c.uid,
        'gc_number', c.gc_number,
        'gc_barcode', c.gc_barcode,
        'qrcode', c.qrcode,
        'pack_number', c.pack_number,
        'nama_gc', c.nama_gc,
        'duration_minutes', c.duration_minutes,
        'background_image_url', c.background_image_url,
        'expired_date', c.expired_date,
        'id_payment_buy', c.id_payment_buy,
        'activated_at', c.activated_at
      )
      ORDER BY c.gc_number ASC
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM public.ot_pos_gc_compliment c
  WHERE c.uid = ANY(v_unique_uids);

  RETURN jsonb_build_object(
    'id_payment_buy', v_id_payment,
    'pack_number', v_pack,
    'buy_at', v_buy_at,
    'expired_date', v_expired_date,
    'activated_count', v_locked_count,
    'rows', v_rows
  );
END;
$$;

REVOKE ALL ON FUNCTION public.activate_pos_gc_compliments(UUID[], TEXT, TIMESTAMPTZ, DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.activate_pos_gc_compliments(UUID[], TEXT, TIMESTAMPTZ, DATE) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 7. RPC: public.get_pos_gc_compliment_list(...)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_pos_gc_compliment_list(
  p_start_date DATE DEFAULT NULL,
  p_end_date DATE DEFAULT NULL,
  p_is_active TEXT DEFAULT 'ALL',
  p_has_used TEXT DEFAULT 'ALL',
  p_web_service_id UUID DEFAULT NULL,
  p_search TEXT DEFAULT NULL,
  p_page INTEGER DEFAULT 1,
  p_page_size INTEGER DEFAULT 50
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_uid UUID;
  v_actor_role INTEGER;
  v_actor_outlet TEXT;
  v_actor_name TEXT;

  v_is_active TEXT := UPPER(COALESCE(NULLIF(TRIM(p_is_active), ''), 'ALL'));
  v_has_used TEXT := UPPER(COALESCE(NULLIF(TRIM(p_has_used), ''), 'ALL'));
  v_search TEXT := NULLIF(TRIM(COALESCE(p_search, '')), '');
  v_page INTEGER := GREATEST(COALESCE(p_page, 1), 1);
  v_page_size INTEGER := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 2000);
  v_offset INTEGER;

  v_total_count INTEGER := 0;
  v_summary JSONB;
  v_rows JSONB := '[]'::jsonb;
BEGIN
  SELECT user_uid, user_role, user_outlet, user_name
  INTO v_actor_uid, v_actor_role, v_actor_outlet, v_actor_name
  FROM public._assert_gc_compliment_access();

  IF v_search IS NULL AND p_start_date IS NOT NULL AND p_end_date IS NOT NULL AND p_start_date > p_end_date THEN
    RAISE EXCEPTION 'Tanggal mulai tidak boleh lebih besar dari tanggal akhir.' USING ERRCODE = '22023';
  END IF;

  v_offset := (v_page - 1) * v_page_size;

  WITH base AS (
    SELECT
      c.uid,
      c.gc_number,
      c.gc_barcode,
      c.qrcode,
      COALESCE(tx.pack_number, c.pack_number) AS pack_number,
      c.web_service_id,
      c.service_name,
      c.service_category,
      c.duration_minutes,
      c.background_image_url,
      c.nama_gc,
      COALESCE(c.harga_jasa, 0)::numeric(15, 2) AS harga_jasa,
      COALESCE(c.harga_jual, 0)::numeric(15, 2) AS harga_jual,
      c.kode_outlet,
      c.image_url,
      c.is_active,
      c.is_sold,
      COALESCE(tx.has_used, c.has_used, false) AS has_used,
      tx.used_at,
      tx.kode_outlet_used,
      mo_used.name_outlet AS outlet_used_name,
      COALESCE(tx.expired_date, c.expired_date) AS expired_date,
      COALESCE(tx.id_payment_buy, c.id_payment_buy) AS id_payment_buy,
      c.activated_at,
      c.activated_by,
      c.activated_by_name,
      c.notes,
      c.email_sent_to,
      c.email_sent_at,
      c.created_at,
      c.created_by,
      c.created_by_name
    FROM public.ot_pos_gc_compliment c
    LEFT JOIN public.ot_pos_gc_transaction tx ON tx.gc_number = c.gc_number
    LEFT JOIN public.master_outlet mo_used ON mo_used.kode_outlet = tx.kode_outlet_used
  ),
  filtered AS (
    SELECT b.*
    FROM base b
    WHERE
      (
        CASE
          WHEN v_search IS NOT NULL THEN
            (
              COALESCE(b.gc_number, '') ILIKE '%' || v_search || '%'
              OR COALESCE(b.gc_barcode, '') ILIKE '%' || v_search || '%'
              OR COALESCE(b.qrcode, '') ILIKE '%' || v_search || '%'
              OR COALESCE(b.pack_number, '') ILIKE '%' || v_search || '%'
              OR COALESCE(b.nama_gc, '') ILIKE '%' || v_search || '%'
              OR COALESCE(b.notes, '') ILIKE '%' || v_search || '%'
              OR COALESCE(b.id_payment_buy, '') ILIKE '%' || v_search || '%'
            )
          ELSE
            (
              (p_start_date IS NULL OR (b.created_at AT TIME ZONE 'Asia/Jakarta')::date >= p_start_date)
              AND (p_end_date IS NULL OR (b.created_at AT TIME ZONE 'Asia/Jakarta')::date <= p_end_date)
            )
        END
      )
      AND (
        v_is_active = 'ALL'
        OR (v_is_active = 'TRUE' AND b.is_active = true)
        OR (v_is_active = 'FALSE' AND b.is_active = false)
      )
      AND (
        v_has_used = 'ALL'
        OR (v_has_used = 'TRUE' AND b.has_used = true)
        OR (v_has_used = 'FALSE' AND b.has_used = false)
      )
      AND (
        p_web_service_id IS NULL OR b.web_service_id = p_web_service_id
      )
  ),
  agg AS (
    SELECT
      COUNT(*)::integer AS total_count,
      COALESCE(SUM(f.harga_jasa), 0)::numeric(15, 2) AS total_harga_jasa,
      COUNT(*) FILTER (WHERE f.is_active = false)::integer AS draft_count,
      COUNT(*) FILTER (WHERE f.is_active = true AND f.has_used = false)::integer AS active_unused_count,
      COUNT(*) FILTER (WHERE f.has_used = true)::integer AS used_count
    FROM filtered f
  ),
  paged AS (
    SELECT f.*
    FROM filtered f
    ORDER BY f.created_at DESC, f.gc_number ASC
    LIMIT v_page_size
    OFFSET v_offset
  )
  SELECT
    a.total_count,
    jsonb_build_object(
      'total_count', a.total_count,
      'total_harga_jasa', a.total_harga_jasa,
      'draft_count', a.draft_count,
      'active_unused_count', a.active_unused_count,
      'used_count', a.used_count
    ),
    COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'uid', p.uid,
          'gc_number', p.gc_number,
          'gc_barcode', p.gc_barcode,
          'qrcode', p.qrcode,
          'pack_number', p.pack_number,
          'web_service_id', p.web_service_id,
          'service_name', p.service_name,
          'service_category', p.service_category,
          'duration_minutes', p.duration_minutes,
          'background_image_url', p.background_image_url,
          'nama_gc', p.nama_gc,
          'harga_jasa', p.harga_jasa,
          'harga_jual', p.harga_jual,
          'kode_outlet', p.kode_outlet,
          'image_url', p.image_url,
          'is_active', p.is_active,
          'is_sold', p.is_sold,
          'has_used', p.has_used,
          'used_at', p.used_at,
          'kode_outlet_used', p.kode_outlet_used,
          'outlet_used_name', p.outlet_used_name,
          'expired_date', p.expired_date,
          'id_payment_buy', p.id_payment_buy,
          'activated_at', p.activated_at,
          'activated_by', p.activated_by,
          'activated_by_name', p.activated_by_name,
          'notes', p.notes,
          'email_sent_to', p.email_sent_to,
          'email_sent_at', p.email_sent_at,
          'created_at', p.created_at,
          'created_by', p.created_by,
          'created_by_name', p.created_by_name
        )
        ORDER BY p.created_at DESC, p.gc_number ASC
      )
      FROM paged p
    ), '[]'::jsonb)
  INTO v_total_count, v_summary, v_rows
  FROM agg a;

  RETURN jsonb_build_object(
    'summary', COALESCE(v_summary, jsonb_build_object(
      'total_count', 0,
      'total_harga_jasa', 0,
      'draft_count', 0,
      'active_unused_count', 0,
      'used_count', 0
    )),
    'pagination', jsonb_build_object(
      'page', v_page,
      'page_size', v_page_size,
      'total_count', COALESCE(v_total_count, 0),
      'total_pages', GREATEST(CEIL(COALESCE(v_total_count, 0)::numeric / v_page_size)::integer, 1)
    ),
    'rows', COALESCE(v_rows, '[]'::jsonb)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_pos_gc_compliment_list(DATE, DATE, TEXT, TEXT, UUID, TEXT, INTEGER, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_pos_gc_compliment_list(DATE, DATE, TEXT, TEXT, UUID, TEXT, INTEGER, INTEGER) TO authenticated, service_role;

-- Reload PostgREST schema cache
NOTIFY pgrst, 'reload schema';
